'use strict';

process.stdin.resume();
process.stdin.setEncoding('utf-8');

let inputString = '';
let currentLine = 0;

process.stdin.on('data', inputStdin => {
    inputString += inputStdin;
});

process.stdin.on('end', _ => {
    inputString = inputString.trim().split('\n').map(string => {
        return string.trim();
    });
    
    main();    
});

function readline() {
    return inputString[currentLine++];
}

function output(x) {
    if (typeof x !== 'string') {
        x = x.toString();
    }
    //process.stdout.write(x);   // without auto '\n' (newline)
    console.log(x);  // with auto '\n' (newline)
}

function main() {
    let N = readline();

    for (let test = 0; test < N; test++) {
        let f = readline().split(' ').map(Number);
        let s = readline().split(' ').map(Number);

        let result = 2;
        if (f[0] === 0 && f[1] === 0 && s[0] === 0 && s[1] === 0) {
            result = 0;
        } else if (f[0] + f[1] + s[0] + s[1] === 4) {
            result = 2;
        } else {
            result = 1;
        }

        output(result);
    }
}
